insert into public.legal_documents(slug,language,version,effective_at,title,summary,sections,status) values
('sponsorship','es','1.1',now(),'Condiciones de Patrocinio','Patrocinios de 30 días contratados desde el panel mediante Stripe, con tres niveles y reglas de privacidad.','[{"heading":"Contratación y duración","body":"La cuenta que gestiona el local puede contratar desde su panel un patrocinio de 30 días, con fecha de inicio seleccionada. Stripe muestra el importe antes de pagar. El patrocinio se activa únicamente cuando el servidor confirma el pago; volver del Checkout no lo activa. Los huecos por ciudad son limitados y una reserva de pago pendiente caduca a las 24 horas."},{"heading":"Niveles","body":"Destacado: pin etiquetado en el mapa y elegibilidad para tarjetas patrocinadas. Destacado Plus: añade prioridad en los listados compatibles. Top: aparece antes que Plus y permite Flash Alerts. Importes actuales de prueba: 29 €, 49 € y 79 € respectivamente por 30 días. No hay renovación automática del patrocinio."},{"heading":"Reglas fijas","body":"El patrocinio siempre se etiqueta, no altera los datos de afluencia y respeta los filtros y la visibilidad del local. Las tarjetas del swipe solo muestran locales cercanos y abiertos, como máximo una por cada diez perfiles. El Pase elimina estas tarjetas. No se usan redes publicitarias ni rastreo de terceros."},{"heading":"Flash Alerts y alcohol","body":"Flash Alerts requiere un patrocinio Top activo. Solo llega a mayores con edad verificada y consentimiento de comunicaciones comerciales. Las promociones de alcohol permanecen desactivadas; su habilitación exige revisar la normativa aplicable."},{"heading":"Estadísticas Pro y entorno de pruebas","body":"Estadísticas Pro es una suscripción independiente por local, actualmente 19,99 € al mes en pruebas. Se renueva automáticamente hasta cancelarla desde el Portal de Stripe y conserva acceso hasta finalizar el periodo pagado; muestra agregados con umbrales de anonimato. Todos los importes de esta versión son provisionales de Stripe TEST, no cargos reales. La activación de pagos reales queda pendiente de revisión jurídica, fiscal y de empresa."}]'::jsonb,'published'),
('sponsorship','en','1.1',now(),'Sponsorship Terms','30-day sponsorships purchased through Stripe from the venue panel, with three tiers and privacy rules.','[{"heading":"Purchase and duration","body":"The account managing the venue can purchase a 30-day sponsorship from its panel and choose a start date. Stripe displays the amount before payment. Sponsorship activates only after the server confirms payment; returning from Checkout does not activate it. City slots are limited, and an unpaid reservation expires after 24 hours."},{"heading":"Tiers","body":"Featured: a labelled map pin and eligibility for sponsored cards. Featured Plus: also adds priority in matching venue lists. Top: appears before Plus and enables Flash Alerts. Current test prices are €29, €49 and €79 respectively for 30 days. Sponsorship does not renew automatically."},{"heading":"Fixed rules","body":"Sponsorship is always labelled, never changes attendance figures and respects venue filters and visibility. Swipe cards show only nearby open venues, at most one per ten profiles. The Pass removes these cards. No third-party ad networks or tracking are used."},{"heading":"Flash Alerts and alcohol","body":"Flash Alerts requires an active Top sponsorship. It reaches only age-verified adults who consented to marketing communications. Alcohol promotions remain disabled; enabling them requires reviewing applicable rules."},{"heading":"Venue Pro and testing","body":"Venue Pro statistics is a separate subscription per venue, currently €19.99 per month in testing. It renews automatically until cancelled in the Stripe Portal, retains access through the paid period and displays aggregates with anonymity thresholds. All amounts in this version are provisional Stripe TEST prices, not real charges. Live payments remain subject to legal, tax and company review."}]'::jsonb,'published');
